// ======================================================
// WF4 - NORMALIZAR EVENTOS V10
// Entrada: /calendario-json del bridge
// Mode: Run Once for All Items
// ======================================================

const entrada = $input.first().json ?? {};

if (entrada.ok !== true) {
  throw new Error(
    entrada.mensaje ??
    'El bridge no devolvió un calendario válido.'
  );
}

if (!Array.isArray(entrada.eventos)) {
  throw new Error(
    'El bridge no devolvió el arreglo eventos.'
  );
}

if (!entrada.eventos.length) {
  throw new Error(
    'El calendario fue procesado pero no contiene eventos.'
  );
}

const requeridos = [
  'departamento',
  'nombre_evento',
  'fuente_archivo',
  'hash_evento'
];

const salida = [];

for (const evento of entrada.eventos) {

  const faltantes =
    requeridos.filter(
      campo =>
        evento[campo] === null ||
        evento[campo] === undefined ||
        String(evento[campo]).trim() === ''
    );

  if (faltantes.length) {

    throw new Error(
      `Evento inválido. Faltan campos: ${faltantes.join(', ')}. ` +
      `Evento: ${JSON.stringify(evento)}`
    );
  }

  salida.push({
    json: evento
  });
}

return salida;

const query =
  $json.query ?? {};

function texto(v) {
  if (
    v === null ||
    v === undefined ||
    String(v).trim() === ''
  ) {
    return null;
  }

  return String(v).trim();
}

function fecha(v) {

  const s = texto(v);

  if (!s) return null;

  if (
    !/^\d{4}-\d{2}-\d{2}$/
      .test(s)
  ) {

    throw new Error(
      `Fecha inválida: ${s}. Usa YYYY-MM-DD.`
    );
  }

  return s;
}


return [{
  json: {

    desde:
      fecha(query.desde),

    hasta:
      fecha(query.hasta),

    departamento:
      texto(query.departamento),

    modalidad:
      texto(query.modalidad),

    entidad:
      texto(query.entidad),

    busqueda:
      texto(query.q),

    limite:
      Math.min(
        Number(query.limite ?? 200),
        500
      )
  }
}];

const entrada =
  $input.first().json ?? {};

const error =
  entrada.error ??
  entrada;

const statusCode =
  error.statusCode ??
  error.httpCode ??
  entrada.statusCode ??
  'sin código';

const mensaje =
  error.message ??
  entrada.message ??
  'No se pudo consultar el calendario MIDAGRI';

throw new Error(
  `[WF4 - Calendario MIDAGRI] ` +
  `Error en HTTP Request. ` +
  `Estado: ${statusCode}. ` +
  `Detalle: ${mensaje}. ` +
  `La actualización fue cancelada y PostgreSQL conserva la última carga válida.`
);
